--
-- Table structure for table `partita`
--

DROP TABLE IF EXISTS `partita`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `partita` (
  `partita_id` int(11) NOT NULL AUTO_INCREMENT,
  `stagione_id` varchar(9) NOT NULL,
  `data` date NOT NULL,
  `team_casa` varchar(3) NOT NULL,
  `team_ospite` varchar(3) NOT NULL,
  `sede_neutra` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`partita_id`),
  UNIQUE KEY `uk_partita` (`stagione_id`,`data`,`team_casa`,`team_ospite`),
  KEY `idx_partita_ospite` (`stagione_id`,`team_ospite`,`data`),
  KEY `idx_partita_casa` (`stagione_id`,`team_casa`,`data`),
  KEY `fk_partita_casa` (`team_casa`),
  KEY `fk_partita_ospite` (`team_ospite`),
  CONSTRAINT `fk_partita_casa` FOREIGN KEY (`team_casa`) REFERENCES `team` (`team_id`),
  CONSTRAINT `fk_partita_ospite` FOREIGN KEY (`team_ospite`) REFERENCES `team` (`team_id`),
  CONSTRAINT `fk_partita_stagione` FOREIGN KEY (`stagione_id`) REFERENCES `stagione` (`stagione_id`),
  CONSTRAINT `ck_partita_diversi` CHECK (`team_casa` <> `team_ospite`)
) ENGINE=InnoDB AUTO_INCREMENT=6151 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

